def predecessor(raw):
    if type(raw) is not bytes:
        raise ValueError("exact bytes required for OWNER proof")
    digest = hashlib.sha256(raw).hexdigest()
    if len(raw) == BEFORE_BYTES and digest == BEFORE_SHA256:
        return raw
    if len(raw) != AFTER_BYTES or digest != AFTER_SHA256:
        raise ValueError("unreviewed complete OWNER source")
    proof = raw
    for current, original in _INVERSE:
        if proof.count(current) != 1:
            raise ValueError("unique complete OWNER inverse block required")
        proof = proof.replace(current, original, 1)
    if len(proof) != BEFORE_BYTES or hashlib.sha256(proof).hexdigest() != BEFORE_SHA256:
        raise ValueError("complete preceding OWNER source required")
    return proof
